let myBirth={date:'1999-05-18',time:'09:30',unknown:false,demo:true};
const demoBirths={1:{date:'2000-06-12',time:'09:20'},2:{date:'2001-03-18',time:'17:40'},3:{date:'1998-11-04',time:'06:30'}};
const chartCache=new Map();
function birthChart(b){const key=JSON.stringify(b);if(!chartCache.has(key))chartCache.set(key,Bazi.chart(b));return chartCache.get(key)}
function candidateMatch(p){if(myBirth.demo)return {score:null,parts:[],label:'待填写我的生辰'};return Bazi.match(birthChart(myBirth),birthChart(demoBirths[p.id]))}
function adultAge(date){const [y,m,d]=date.split('-').map(Number),now=new Date();return now.getFullYear()-y-((now.getMonth()+1<m||(now.getMonth()+1===m&&now.getDate()<d))?1:0)}
function pillarMarkup(chart){return `<div class="four-pillars">${chart.pillars.map((p,i)=>`<div><small>${['年柱','月柱','日柱','时柱'][i]}</small><strong>${p?`<span class="element-${Bazi.stemElements[p[0]]}">${p[0]}</span><span class="element-${Bazi.branchElements[p[1]]}">${p[1]}</span>`:'<span>待</span><span>定</span>'}</strong></div>`).join('')}</div>`}
function baziProfileStrip(p){const result=candidateMatch(p);return `<button class="bazi-inline" data-compare="${p.id}"><span>${icon('sparkle')}八字合缘</span><strong>${result.score===null?'待补充时辰':result.score+' 分'} ${icon('chevron')}</strong></button>`}
function renderBazi(){
  const chart=birthChart(myBirth),ranked=pool().slice().sort((a,b)=>(candidateMatch(b).score??0)-(candidateMatch(a).score??0));
  return heading('从生辰，遇见合拍的人','八字合缘 · 把传统文化变成认识彼此的起点。',`<button class="outline-btn" data-action="bazi-rules">${icon('sparkle')}合缘规则</button>`)+`<div class="bazi-layout"><section class="birth-section"><div class="birth-form-card"><div class="bazi-section-title"><h2>我的生辰</h2><span>${myBirth.demo?'示例资料':'本次填写'}</span></div><form id="birth-form"><label class="field">出生日期 · 公历<input type="date" name="date" aria-label="公历出生日期" min="1900-01-01" value="${myBirth.date}" required></label><label class="field">出生时间<input type="time" name="time" aria-label="出生时间" value="${myBirth.unknown?'':myBirth.time}" ${myBirth.unknown?'disabled':'required'}></label><label class="unknown-hour"><input type="checkbox" name="unknown" ${myBirth.unknown?'checked':''}>不清楚出生时辰</label><p class="birth-note">按东八区标准时间（UTC+8）排盘。请先换算夏令时或海外当地时间；本版不校正真太阳时。</p><button class="primary-btn full" type="submit">${icon('sparkle')}排盘并重新匹配</button></form><p class="privacy-note">${icon('shield')}生辰仅在此页面计算，刷新后重置。</p></div><div class="my-chart-card"><div class="chart-title"><span>我的四柱</span><small>${chart.complete?'时辰已知':'时辰待补充'}</small></div>${pillarMarkup(chart)}<div class="day-element">日主 <strong>${chart.dayStem} · ${chart.dayElement}</strong><span>公历 ${myBirth.date}</span></div>${chart.uncertain?'<p class="boundary-note">当天跨越节气，年柱或月柱也需时辰确认。</p>':''}</div></section><section class="bazi-results"><div class="bazi-section-title"><h2>为你合缘 <span class="result-count">${ranked.length}</span></h2><button class="view-link" data-action="filter">年龄与距离偏好</button></div><p class="result-note">${chart.complete?'按合缘参考分排序，同分时优先共同兴趣。':'生辰信息不完整，暂不评分与排序。'}候选资料均为虚构。</p>${ranked.length?ranked.map((p,i)=>{const r=candidateMatch(p),shared=p.tags.filter(t=>myInterests.includes(t));return `<article class="bazi-person"><div class="bazi-person-main"><button class="candidate-photo" data-open-person="${p.id}" aria-label="查看${esc(p.name)}资料"><img src="${p.image}" alt="${esc(p.name)}的资料头像"><span>${String(i+1).padStart(2,'0')}</span></button><div class="candidate-info"><h3>${esc(p.name)}<span>${adultAge(demoBirths[p.id].date)} 岁</span></h3><p>${esc(p.job)} · ${p.km===null?'距离未填写':p.km+' km'}</p><div class="candidate-shared">${shared.length?'共同兴趣：'+esc(shared.slice(0,2).join('、')):'从新的兴趣开始认识'}</div></div><div class="bazi-score"><strong>${r.score===null?'—':r.score}</strong><span>${r.score===null?'待补充':'合缘参考 / 100'}</span></div></div><div class="bazi-person-detail"><span>${r.score===null?'补充时辰后查看合缘参考':r.parts[0].detail}</span><button class="score-details" data-compare="${p.id}">查看合缘解读 ${icon('chevron')}</button></div><div class="candidate-actions"><button class="outline-btn" data-open-person="${p.id}">了解 ${esc(p.name)}</button><button class="primary-btn" data-contact="${p.id}">联系方式 ${icon('chat')}</button></div></article>`}).join(''):`<div class="empty">${icon('heart')}<h2>暂时没有新的候选</h2><p>可以调整偏好，或者去看看已经喜欢的人。</p><button class="outline-btn" data-action="filter">调整偏好</button><button class="primary-btn" data-page="likes">查看喜欢</button></div>`}<div class="culture-note"><strong>缘分的开始，由你决定。</strong><p>合缘参考分来自自定义规则，仅作传统文化趣味参考，不代表恋爱成功率。彼此的意愿、价值观与真实相处更值得了解。</p></div></section></div>`
}
function compareBazi(id){const p=people.find(p=>p.id===id),a=birthChart(myBirth),b=birthChart(demoBirths[id]),r=candidateMatch(p);modal(`<div class="dialog-head"><h2>你与${esc(p.name)}的合缘</h2>${closeButton()}</div><div class="compare-score"><strong>${r.score??'—'}</strong><span>${r.score===null?'时辰不完整，暂不评分':'合缘参考 / 100'}</span></div><div class="compare-charts"><section><h3>你${myBirth.demo?' · 示例':''}</h3>${pillarMarkup(a)}</section><section><h3>${esc(p.name)} · 候选资料</h3>${pillarMarkup(b)}</section></div><div class="score-parts">${r.parts.map(part=>`<section><div><strong>${part.name}</strong><span>${part.value} / ${part.max}</span></div><p>${part.detail}</p></section>`).join('')}</div>${r.score===null?'<p class="muted">请补充出生时间。时柱不会用一个假定时间代替。</p>':''}<p class="muted">字面五行计数不等于旺衰或喜用神分析；「合」「冲」为传统关系名称，不用于判断一段关系的好坏。</p><button class="outline-btn full" data-action="bazi-rules">查看计算规则与排盘口径</button><button class="primary-btn full compare-chat" data-contact="${p.id}">查看联系方式</button>`);dialog.classList.add('bazi-dialog')}
function showBaziRules(){if(dialog.open)dialog.close();modal(`<div class="dialog-head"><h2>合缘参考如何计算</h2>${closeButton()}</div><p class="muted">这是本软件自定义的趣味排序规则，不是经过验证的关系预测，也不是传统命理的统一评分标准。</p><div class="rule-row"><strong>日干五行 · 30 分</strong><p>相生 30，同五行 22，相克 12。比较双方日干所属五行。</p></div><div class="rule-row"><strong>日支关系 · 30 分</strong><p>六合 30，同支 22，六冲 10，其他 18。只比较双方日支。</p></div><div class="rule-row"><strong>字面五行覆盖 · 40 分</strong><p>将双方四柱的天干五行与地支本气合并，每出现一种五行计 8 分。此项仅表示覆盖种类，不判断喜用神。</p></div><div class="rule-row"><strong>排盘口径</strong><p>公历、东八区标准时间；年柱以立春、月柱以节交接时刻划分；日柱按午夜换日（晚子时仍属当天）。时辰不详时不显示时柱、不计分；节气交接当天还会标注年柱或月柱待定。</p></div><div class="rule-row"><strong>候选范围与排序</strong><p>先按年龄、距离偏好筛选未喜欢且未跳过的人，再按本分数降序排列。同分优先共同兴趣数量，仅对本地录入的资料进行推荐。</p></div><p class="muted">排盘工具：<a href="https://github.com/6tail/lunar-javascript" target="_blank" rel="noopener noreferrer">lunar-javascript 1.7.7（MIT）</a>。示例生辰为虚构，其余信息由你录入。</p>`);dialog.classList.add('bazi-dialog')}
document.addEventListener('change',e=>{if(e.target.matches('#birth-form [name=unknown]')){const time=document.querySelector('#birth-form [name=time]');time.disabled=e.target.checked;time.required=!e.target.checked;if(e.target.checked)time.value='';else time.value=myBirth.time||'09:30'}});
document.addEventListener('submit',e=>{if(e.target.id!=='birth-form')return;e.preventDefault();const data=new FormData(e.target);try{const next={date:data.get('date'),time:data.get('time')||'',unknown:data.has('unknown'),demo:false};if(!String(data.get('nickname')||'').trim())throw Error('请填写昵称');birthChart(next);const age=adultAge(next.date);if(age<18||age>100)throw Error('本软件仅面向18岁及以上成年人，请检查出生日期');myBirth=next;profile.age=age;index=0;render();toast(next.unknown?'已排出可确定的三柱，补充时辰后可匹配':'已重新排盘，合缘推荐已更新')}catch(err){toast(err.message)}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.compare)compareBazi(Number(b.dataset.compare));if(b.dataset.openPerson){const id=Number(b.dataset.openPerson);mode='for-you';index=pool().findIndex(p=>p.id===id);if(index<0){index=0;toast('这位朋友暂不在当前推荐中');return}navigate('discover')}if(b.dataset.action==='bazi-rules')showBaziRules()});
document.addEventListener('DOMContentLoaded',()=>{document.getElementById('dialog').addEventListener('close',()=>dialog.classList.remove('bazi-dialog'))});
